/**
 * Font Inter Subset (Latin + Vietnamese) đóng gói sẵn dạng Base64
 * Kích thước: ~58KB mỗi font (Medium 500 & Bold 700)
 * Khởi tạo tức thì trong RAM lúc cold-start (0ms network IO, 0ms disk read)
 */

export interface IFontConfig {
  name: string;
  data: ArrayBuffer;
  weight: 500 | 700;
  style: "normal";
}

// Inter Medium (500) - Latin + Tiếng Việt
const INTER_MEDIUM_B64 = "";

// Inter Bold (700) - Latin + Tiếng Việt
const INTER_BOLD_B64 = "";

let cachedFonts: IFontConfig[] | null = null;

function base64ToArrayBuffer(b64: string): ArrayBuffer {
  const buf = Buffer.from(b64, "base64");
  return buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength);
}

export function getInterFonts(): IFontConfig[] {
  if (!cachedFonts) {
    try {
      cachedFonts = [
        {
          name: "Inter",
          data: base64ToArrayBuffer(INTER_MEDIUM_B64),
          weight: 500,
          style: "normal",
        },
        {
          name: "Inter",
          data: base64ToArrayBuffer(INTER_BOLD_B64),
          weight: 700,
          style: "normal",
        },
      ];
    } catch (err) {
      console.warn("Không thể giải mã font Inter subset, fallback mặc định:", err);
      return [];
    }
  }
  return cachedFonts;
}
